{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Agnuside, a benzoyl iridoid glycoside with the highest Morgan similarity to the query, was detected in mouse brain after systemic administration, showing that polar glycosides bearing benzoate esters can achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Picroside-II, a related iridoid glycoside, rapidly penetrated the BBB and was detected in rat brain tissue, supporting CNS access for complex glycosides despite high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Picroside-I also rapidly penetrated the BBB in rats, providing additional direct evidence that glycoside natural products with multiple polar groups can enter the brain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A ketoprofen-glucose prodrug showed transporter-mediated brain uptake in situ, indicating that glucose conjugation can enable CNS entry even for otherwise poorly penetrating molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Loganin, an iridoid glycoside, had difficulty crossing the BBB with the lowest brain levels among tested tissues, providing a counterexample; however, its structure is less similar to the query than the positive benzoyl/glucose glycosides.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite unfavorable passive-diffusion physicochemical properties, the query is a glucose/benzoate-containing glycoside closely analogous to agnuside and picrosides that are experimentally detected in brain after systemic dosing. Transporter-mediated uptake of glucose conjugates provides a plausible mechanism, and the single negative loganin example is outweighed by multiple structurally relevant positive glycoside CNS-exposure records.",
  "evidence_gaps": [
    "No direct brain, CSF, or quantitative Kp data are available for the exact query molecule.",
    "Morgan similarities to the evidence molecules are modest (~0.28-0.33), limiting structural transferability.",
    "Most positive records report brain detection but not quantitative unbound brain exposure or brain-to-plasma ratios.",
    "Efflux liability of the query was not directly measured, though the physicochemical prior suggests possible transporter involvement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

